import sys


def main():
    flags = []
    filename = None

    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and not arg.startswith('--'):
            for ch in arg[1:]:
                if ch in ('l', 'w', 'c'):
                    flags.append(ch)
                else:
                    print(f"Unknown flag: -{ch}", file=sys.stderr)
                    sys.exit(1)
        elif arg == '-':
            filename = '-'
        elif filename is None:
            filename = arg
        else:
            print(f"Unexpected argument: {arg}", file=sys.stderr)
            sys.exit(1)
        i += 1

    # Determine which counters to show (default all three)
    if not flags:
        flags = ['l', 'w', 'c']

    # Read input
    if filename == '-' or filename is None:
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    # Count characters (bytes)
    char_count = len(data)

    # Count lines
    # A final line with no trailing newline still counts as a line
    if len(data) == 0:
        line_count = 0
    else:
        line_count = data.count(b'\n')
        if not data.endswith(b'\n'):
            line_count += 1

    # Count words
    word_count = len(data.decode('utf-8', errors='surrogateescape').split())

    # Output in fixed order: l, w, c
    results = []
    for flag in flags:
        if flag == 'l':
            results.append(str(line_count))
        elif flag == 'w':
            results.append(str(word_count))
        elif flag == 'c':
            results.append(str(char_count))

    print(' '.join(results))


if __name__ == '__main__':
    main()

